@Component("payrollCalendar-handler")
@ProcessingGroup("payrollCalendar-processing-group")
public class PayrollCalendarEventHandler {
	
	// core constructor
	PayrollCalendarEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePayrollCalendarEvent
     */
    @EventHandler
    public void handle( CreatePayrollCalendarEvent event) {
        entityManager.persist(new PayrollCalendar(event.getPayrollCalendarId(), event.getName(), event.getCountry(), event.getOrganization(), event.getPayrollRuns(), event.getEmployees(), event.getPayFrequency()));
    }

    /*
     * @param	event UpdatePayrollCalendarEvent
     */
    @EventHandler
    public PayrollCalendar handle( UpdatePayrollCalendarEvent event) {
    	entityManager.merge(new PayrollCalendar(event.getPayrollCalendarId(), event.getName(), event.getCountry(), event.getOrganization(), event.getPayrollRuns(), event.getEmployees(), event.getPayFrequency()));
    }
    
    /*
     * @param	event DeletePayrollCalendarEvent
     */
    @EventHandler
    public void on( DeletePayrollCalendarEvent event) {
    	PayrollCalendar entity = new PayrollCalendar();
   
    	// ------------------------------------------
    	// apply the PayrollCalendarId
    	// ------------------------------------------
    	entity.setPayrollCalendarId( event.getPayrollCalendarId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PayrollCalendarRepository payrollCalendarEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PayrollCalendarEventHandler.class.getName());

}
